diff --git a/src/config/load.ts b/src/config/load.ts
--- a/src/config/load.ts
+++ b/src/config/load.ts
@@ -2,5 +2,5 @@
 import {parseConfig} from "./parse";
 import type {Config} from "./types";

-export const loadConfig = (path: string): Config =>
-    parseConfig(readFileSync(path, "utf8"));
+export const loadConfig = (path: string, strict = false): Config =>
+    parseConfig(readFileSync(path, "utf8"), strict);
diff --git a/src/config/parse.ts b/src/config/parse.ts
--- a/src/config/parse.ts
+++ b/src/config/parse.ts
@@ -1,7 +1,7 @@
 import {validateKeys} from "./validate";
 import type {Config} from "./types";

-export const parseConfig = (text: string): Config => {
+export const parseConfig = (text: string, strict: boolean): Config => {
     const raw: unknown = JSON.parse(text);
-    return validateKeys(raw);
+    return validateKeys(raw, strict);
 };
diff --git a/src/config/validate.ts b/src/config/validate.ts
--- a/src/config/validate.ts
+++ b/src/config/validate.ts
@@ -2,12 +2,15 @@

 const KNOWN = new Set(["name", "port", "logLevel"]);

-export const validateKeys = (raw: unknown): Config => {
+export const validateKeys = (raw: unknown, strict: boolean): Config => {
     if (typeof raw !== "object" || raw === null) {
         throw new Error("config must be an object");
     }
     for (const key of Object.keys(raw)) {
         if (!KNOWN.has(key)) {
+            if (strict) {
+                throw new Error(`config: unknown key "${key}"`);
+            }
             console.warn(`config: unknown key "${key}" ignored`);
         }
     }
diff --git a/src/main.ts b/src/main.ts
--- a/src/main.ts
+++ b/src/main.ts
@@ -1,4 +1,4 @@
 import {loadConfig} from "./config/load";
 import {serve} from "./server";

-serve(loadConfig(process.env.CONFIG_PATH ?? "config.json"));
+serve(loadConfig(process.env.CONFIG_PATH ?? "config.json", true));
